window.RP_SESSION={"id":"S-bf2bb3cc20cc","messages":[{"id":"RP-0174773","time":"2026-06-15T22:18:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"오늘도 평화로운 어용 어용 어용 대장간.","characters":["P-55e987e3c831"]},{"id":"RP-0174774","time":"2026-06-15T22:18:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"오늘은...","characters":["P-55e987e3c831"]},{"id":"RP-0174775","time":"2026-06-15T22:18:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"\"오늘은 뭐한담...\"","characters":["P-55e987e3c831"]},{"id":"RP-0174776","time":"2026-06-15T22:19:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"전에 숯구덩이 앞에 놔둔 통나무나 작업하러 갑니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174777","time":"2026-06-15T22:19:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그 앞에 걸터 앉아서, 드로우 나이프를 들고 나무껍질을 벗기기 시작하죠.","characters":["P-55e987e3c831"]},{"id":"RP-0174778","time":"2026-06-15T22:21:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"벗긴 나무껍질은 버리지 않고 마대자루에 담아 잘 모아둡니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174779","time":"2026-06-15T22:34:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"배럴보다 넓은 통을 만들까 합니다. 나중에 무두질 같은 것에 쓸 수 있게요.","characters":["P-55e987e3c831"]},{"id":"RP-0174780","time":"2026-06-15T22:34:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"배럴만큼 높지 않고 옆으로 넓은 통이니, 톱을 가져와 적당한 크기로 통나무를 나눠 자릅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174781","time":"2026-06-15T22:36:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그리고 결을 따라 길고 넓은 도끼같은 도구를 사용해 목재를 결대로 쪼개서 판자를 켜기 시작하죠.","characters":["P-55e987e3c831"]},{"id":"RP-0174782","time":"2026-06-15T22:38:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"적당히 안쪽과 아랫부분이 좁아지도록 도끼로 쳐내듯 잘라냅니다. 배럴보다 낮으니까 곡률이 크지는 않게요.","characters":["P-55e987e3c831"]},{"id":"RP-0174783","time":"2026-06-15T22:40:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"대패로 각 판재의 가장자리를 다듬어주고, 연철 재질의 얇은 철 띠를 둘러 가조립 해봅니다. 치수를 재듯 고리를 만들고, 그 안에 각 판자들을 끼워보죠.","characters":["P-55e987e3c831"]},{"id":"RP-0174784","time":"2026-06-15T22:41:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"치수가 얼추 맞으면 철띠에 자를 부분을 표시하고, 도끼로 찍은 뒤 몇번 구부렸다가 피는 걸 반복해서 떼어냅니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174785","time":"2026-06-15T22:42:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"펀치로 리벳 구멍을 뚫고 무른 평리벳으로 철띠를 고정한 다음, 판자들을 원형으로 만 철띠 안에 하나씩 세워 맞춥니다. 맞춰서 거꾸로 된 통 모양으로 만들어 세워요.","characters":["P-55e987e3c831"]},{"id":"RP-0174786","time":"2026-06-15T22:43:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"옆에 대충 철사를 얼기설기 엮어 만든 화로를 놓고 불을 피웁니다. 아직은 형태만 잡아가는 통을 뒤집어 씌우고 안팎에 물을 뿌려서 유연성을 줘요.","characters":["P-55e987e3c831"]},{"id":"RP-0174787","time":"2026-06-15T22:45:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"열과 수분을 가해서 나무가 부러지지 않고 유연하게 휘어지게 합니다. 그 상태에서 쇠사슬을 걸고, 그 위에 강철바를 엮어서 한쪽 방향으로 돌리는 걸로 벌어진 판재들을 안쪽으로 바짝 모읍니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174788","time":"2026-06-15T22:45:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그렇게 모아진 통에 철띠를 하나 더 조립해서 끼우고, 망치로 탕탕 쳐 아래 두꺼운 부분으로 가게 만듭니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174789","time":"2026-06-15T22:47:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"통의 바닥판을 끼울 부분에 크로즈라는 특수 공구를 이용해서 홈을 만듭니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174790","time":"2026-06-15T22:48:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그리고 바닥판이 될 판재들을 나란히 모아, 중간중간 수동 드릴로 구멍을 뚫고 나무 못으로 연결해주죠. 가운데가 두껍고 양 옆으로 갈수록 좀 얇아지는 형상의 나무못입니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174791","time":"2026-06-15T22:49:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"그렇게 만들어진 판재 위에 목공욕 캠퍼스로 원을 그려요. 직경은 만들어진 통 내부 직경을 자로 측정합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174792","time":"2026-06-15T22:50:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"판재를 그루터기 위에 올려 그걸 작업대 삼아 톱질합니다. 둥글게 잘라내고, 가장자리를 비스듬하게 깎아내서 통 안의 홈에 끼울 수 있게 해요.","characters":["P-55e987e3c831"]},{"id":"RP-0174793","time":"2026-06-15T22:51:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"둥근 바닥판을 통 앞에 가져와서, 통 한쪽 끝의 테를 살짝 풀어 헐겁게 만든 뒤, 판을 들어 홈에 끼워 맞춥니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174794","time":"2026-06-15T22:52:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"마지막엔 얇은 쇠막대같은 지렛대를 이용해서 판을 끼워맞추고, 테를 망치로 다시 강하게 박아 판의 가장자리가 빈틈없이 들어가도록 고정합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174795","time":"2026-06-15T22:53:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"다시 빙글 돌려 바닥이 생긴 통을 바닥에 놓고, 강물을 끼얹어 수밀테스트를 하죠.","characters":["P-55e987e3c831"]},{"id":"RP-0174796","time":"2026-06-15T22:55:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-55e987e3c831"]},{"id":"RP-0174797","time":"2026-06-15T22:55:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 12 = 12\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0174798","time":"2026-06-15T22:55:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"보기에 새는 부분도 없고 퍽 괜찮게 만들어진듯 하군요.","characters":["P-55e987e3c831"]},{"id":"RP-0174799","time":"2026-06-15T23:08:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-55e987e3c831"]},{"id":"RP-0174800","time":"2026-06-15T23:10:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"강물을 화로에 끼얹어 꺼버리곤, 나무통을 비스듬히 세우더니 빙글빙글 굴려 대장간으로 갖다 정리합니다.","characters":["P-55e987e3c831"]},{"id":"RP-0174801","time":"2026-06-15T23:10:00+09:00","room":"RP","name":"브랜","profile":"브랜","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-55e987e3c831"]},{"id":"RP-0174802","time":"2026-06-15T23:10:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
